import json, itertools, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# Precompute all valid triples (a,b,c) with a+b=c
triples = []
for a, b, c in itertools.combinations(L, 3):
    if a + b == c:
        triples.append((a, b, c))
    elif a + c == b:
        triples.append((a, c, b))
    elif b + c == a:
        triples.append((b, c, a))
# Depth‑first search for 15 disjoint triples
used = set()
solution = []

def search(start):
    if len(solution) == 15:
        return True
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        # choose this triple
        used.update([a, b, c])
        solution.append((a, b, c))
        if search(i + 1):
            return True
        # backtrack
        used.difference_update([a, b, c])
        solution.pop()
    return False

found = search(0)
if found:
    witness = {
        "polarity": "positive",
        "data": {
            "partition": solution
        }
    }
    print("WITNESS: " + json.dumps(witness))
else:
    witness = {
        "polarity": "negative",
        "basis": "search",
        "search_exhausted": True,
        "nodes_explored": None,
        "method": "depth‑first backtrack",
        "argument": None,
        "domain": None,
        "provisional": False
    }
    print("WITNESS: " + json.dumps(witness))

import json, itertools, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# Precompute possible triples (a,b,c) with a<b and a+b=c
triples = []
Llist = list(L)
for a,b in itertools.combinations(Llist,2):
    c = a+b
    if c in L and c!=a and c!=b:
        triples.append((a,b,c))
# Sort to improve search
triples.sort(key=lambda t: (t[2], t[0]+t[1]))
used = set()
solution = []
# Simple backtracking
sys.setrecursionlimit(10000)

def backtrack(idx):
    if len(solution)==15:
        return True
    if idx>=len(triples):
        return False
    # try next triple
    for i in range(idx, len(triples)):
        a,b,c = triples[i]
        if a in used or b in used or c in used:
            continue
        # choose
        used.update([a,b,c])
        solution.append((a,b,c))
        if backtrack(i+1):
            return True
        # undo
        used.difference_update([a,b,c])
        solution.pop()
    return False

found = backtrack(0)
if found:
    witness = {"polarity":"positive","data":{"partition":solution}}
    print('WITNESS: '+json.dumps(witness))
else:
    # report failure
    witness = {"polarity":"negative","basis":"search","search_exhausted":True,"nodes_explored":len(triples),"method":"simple_backtrack"}
    print('WITNESS: '+json.dumps(witness))
